def shortest_path(graph, source, target):
    # Initialize distances
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    # Initialize predecessor dictionary
    predecessors = {node: None for node in graph}

    # Heap queue algorithm
    # Implements Dijkstra's shortest path algorithm
    from heapq import heappush, heappop
    from collections import defaultdict

    def heapify(start):
        to_process = [(0, start)]  # (distance, node)
        while to_process:
            dist, node = heappop(to_process)
            if dist < distances[node]:
                continue
            for neighbor, weight in graph[node]:
                new_dist = dist + weight
                if new_dist < distances[neighbor]:
                    distances[neighbor] = new_dist
                    predecessors[neighbor] = node
                    heappush(to_process, (new_dist, neighbor))

    heapify(source)

    # Run the heapify process starting from the source
    heapify(source)

    # If there's no path from source to target, distances[target] will be infinity
    if distances[target] == float('inf'):
        return (float('inf'), None)

    # Reconstruct the shortest path
    path = []
    while target:
        path.append(target)
        target = predecessors[target]
    path.reverse()

    return (distances[target], path)
