def shortest_path(graph, source, target):
    from collections import defaultdict
    import heapq

    def bfs(graph, source, target):
        # Track the shortest distance from source to each node
        distances = {node: float('inf') for node in graph}
        distances[source] = 0
        queue = [(0, source)]

        while queue:
            current_distance, current_node = heapq.heappop(queue)

            if current_node == target:
                return current_distance

            for neighbor, weight in graph[current_node]:
                distance = current_distance + weight
                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heapq.heappush(queue, (distance, neighbor))

        return float('inf')

    def dijkstra(graph, source, target):
        # Track the shortest distance from source to each node
        distances = {node: float('inf') for node in graph}
        distances[source] = 0
        priority_queue = [(0, source)]

        while priority_queue:
            current_distance, current_node = heapq.heappop(priority_queue)

            if current_node == target:
                return current_distance

            for neighbor, weight in graph[current_node]:
                distance = current_distance + weight
                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heapq.heappush(priority_queue, (distance, neighbor))

        return float('inf')

    # Determine which algorithm to use based on the graph type
    if all(all(weight >= 0 for _, weight in edges) for edges in graph.values()):
        # Use Dijkstra's algorithm if all weights are non-negative
        return dijkstra(graph, source, target)
    else:
        # Use BFS if the graph contains negative weights
        return bfs(graph, source, target), [source] + bfs(graph, source, target)[1]

